        text["Willkommen"] = "Welcome";
        text["Droplog"] = "Drop log";
        text["Loslegen"] = "Get started";
        text["Silber"] = "Silver";
        text["Zurück"] = "Back";
        text["Weiter"] = "Next";
        text["Mach Grindcrest zu deinem Tracker"] = "Make Grindcrest your tracker";
        text["Lass deine Lootmeldungen sichtbar"] = "Keep your loot notifications visible";
        text["Verbinde die Erfassung mit deinem Spiel"] = "Set up capture for your game";
        text["Stimme deine Silberbewertung ab"] = "Set up your silver valuation";
        text["Deine erste Session kann kommen"] = "Get ready for your first session";
        text["Aus sichtbaren Drops wird deine Session."] = "Visible drops become your session.";
        text["Grindcrest liest die Lootmeldungen im Spielbild und zählt Gegenstände, aktive Grindzeit und Silber. Dafür müssen die Droplogs gut lesbar bleiben."] = "Grindcrest reads loot notifications in the game image to track items, active grind time and silver. The drop logs need to stay clearly readable.";
        text["Dein Verlauf bleibt lokal auf diesem PC. Garmoth-Uploads sind optional und werden separat eingerichtet."] = "Your history stays locally on this PC. Garmoth uploads are optional and set up separately.";
        text["Du kannst die Einrichtung auch ohne geöffnetes Spiel abschließen und die Erfassung später prüfen."] = "You can complete setup without the game open and check capture later.";
        text["Das Droplog darf nicht verdeckt sein."] = "Keep the drop log unobstructed.";
        text["Inventar, Chat, Karte, Spielmeldungen und Overlays dürfen nicht über den Lootzeilen liegen. Verdeckte oder abgeschnittene Drops können fehlen oder falsch gezählt werden."] = "Keep your inventory, chat, map, game notifications and overlays away from the loot lines. Hidden or cropped drops may be missed or counted incorrectly.";
        text["So bereitest du Black Desert vor"] = "Prepare Black Desert";
        text["Öffne Black Desert und lass das Spielfenster sichtbar. Minimiere es während der Erfassung nicht."] = "Open Black Desert and keep the game window visible. Do not minimize it during capture.";
        text["Blende unter „UI bearbeiten“ das normale Droplog und möglichst auch das Special-Droplog ein. Positioniere beide frei und speichere die UI-Einstellungen."] = "In Edit UI, enable the normal drop log and, if possible, the special drop log. Place them in clear areas and save your UI settings.";
        text["Gegenstandsname und Menge müssen vollständig lesbar sein. Verschiebe Menüs und Tracker-Overlays aus diesen Bereichen."] = "The full item name and quantity must be readable. Move menus and tracker overlays away from these areas.";
        text["Nach Änderungen an Schrift, UI-Skalierung, Auflösung oder Profil: UI speichern und die Erfassungsbereiche erneut prüfen. Starte Grindcrest bei einem entsprechenden Hinweis neu."] = "After changing the font, UI scale, resolution or profile, save your UI and check the capture areas again. Restart Grindcrest if prompted.";
        text["Freie Sicht auf deine Drops"] = "A clear view of your drops";
        text["Schema: vollständig sichtbare Lootzeilen mit Gegenstandsname und Menge"] = "Diagram: fully visible loot lines showing item names and quantities";
        text["Normales Droplog · frei halten"] = "Normal drop log · keep clear";
        text["Gegenstandsname"] = "Item name";
        text["Special-Droplog · Name + Menge"] = "Special drop log · name + quantity";
        text["Das normale Droplog ist erforderlich. Ohne eingerichtetes Special-Droplog werden Special-Drops nicht erfasst."] = "The normal drop log is required. Without a configured special drop log, special drops are not tracked.";
        text["Die Skizze zeigt das Prinzip. Deine tatsächlichen Positionen prüfst du im nächsten Schritt."] = "This diagram illustrates the idea. Check your actual positions in the next step.";
        text["Die OCR-Sprache muss zur Spielsprache passen. Die Sprache der Oberfläche ist davon unabhängig."] = "The OCR language must match your game language. The interface language is independent.";
        text["Benötigtes OCR-Sprachpaket: {0}"] = "Required OCR language pack: {0}";
        text["Die Einrichtung startet noch kein Tracking. Falls Spiel oder OCR fehlen, kannst du diese Prüfung später nachholen."] = "Setup does not start tracking. If the game or OCR is unavailable, you can check this later.";
        text["Öffne „Prüfen“ und aktualisiere die Vorschau mit sichtbaren Lootmeldungen: Türkis markiert das normale Droplog, Gold den Textbereich des Special-Droplogs. Name und Menge müssen im Rahmen liegen; Symbol und Verzierung dürfen beim Special-Droplog abgeschnitten sein."] = "Open Check and refresh the preview with loot notifications visible: teal marks the normal drop log, gold the special drop log's text area. The name and quantity must fit inside; the special drop log's icon and decoration may be cropped.";
        text["Wähle in der AP/DP-Anzeige im Spiel die Kategorie deines Grindspots (z. B. Edania, Halbmenschen, Kamasilvia oder Allgemein) und halte die Werte sichtbar. So liest Grindcrest die passenden Gesamtwerte aus."] = "In the game's AP/DP display, select the category for your grind spot (e.g. Edania, Demihuman, Kamasylvian or General) and keep the values visible so Grindcrest can read the matching total stats.";
        text["Silber passend zu deinem Account"] = "Silver values for your account";
        text["Wähle deine Marktregion und trage nur die Verkaufsboni ein, die für deinen Account aktiv sind. So passen die Nettowerte zu deinen Einstellungen."] = "Select your market region and enable only the sale bonuses active on your account. This makes the net values reflect your settings.";
        text["Trashloot und andere NPC-Verkäufe bleiben steuerfrei. Für Marktgegenstände gelten die ausgewählten Boni und die verfügbaren Preise."] = "Trash loot and other NPC sales remain tax-free. Market items use your selected bonuses and the available prices.";
        text["Die Silberwerte sind eine Bewertung deiner Drops. Sie bestätigen keinen tatsächlichen Verkauf."] = "Silver values estimate the value of your drops. They do not confirm an actual sale.";
        text["Deine Einrichtung im Überblick"] = "Your setup at a glance";
        text["Prüfe die Erfassungsbereiche im Spiel, bevor du dich auf die Zählung verlässt. Vergleiche die erste Session mit deinen Inventarmengen."] = "Check the capture areas in the game before relying on the counts. Compare your first session with the quantities in your inventory.";
        text["So startest du deine erste Session"] = "Start your first session";
        text["Wähle in der Live-Session „Tracking starten“. Die aktive Zeit beginnt mit dem ersten neu gezählten Drop."] = "Select Start tracking in Live session. Active time begins with the first newly counted drop.";
        text["Der Spot wird aus deinem Trashloot erkannt. Falls mehrere Gebiete denselben Trashloot haben, wähle die passende Variante."] = "Your spot is detected from your trash loot. If several areas share the same trash loot, select the matching variant.";
        text["Pausieren erhält deine Session. Ohne neuen Loot greift die automatische Pause; die abschließende Leerlaufzeit wird abgezogen."] = "Pausing keeps your session. With no new loot, automatic pause takes over and deducts the trailing idle time.";
        text["Beginne vor einem Spot- oder Charakterwechsel eine neue Session. Deine bisherigen Sessions findest du im Verlauf."] = "Start a new session before changing spots or characters. Find your previous sessions in History.";
        text["Als Nächstes – ganz optional"] = "Next steps — entirely optional";
        text["Unter „Overlay“ kannst du eigene Anzeigen erstellen und aktivieren. Unter „Garmoth“ lässt sich der Upload separat verbinden. Die Loot-Diagnose in den Einstellungen brauchst du nur zur Fehlersuche."] = "Create and enable your own displays under Overlay. Connect uploads separately under Garmoth. Loot diagnostics in Settings are only needed for troubleshooting.";
        text["Vor dem Tracking noch prüfen"] = "Check before tracking";
        text["Spiel, OCR oder Erfassungsbereiche sind noch nicht bereit. Die Live-Session zeigt dir die offenen Schritte; du kannst die Einrichtung trotzdem speichern."] = "The game, OCR or capture areas are not ready yet. Live session will show you what still needs attention; you can save your setup now.";
        text["Einstellungen werden bei Änderungen gespeichert."] = "Settings are saved as you make changes.";
        text["Einrichtung abschließen"] = "Complete setup";
        text["Einrichtung fortsetzen"] = "Continue setup";
        text["Noch neu hier? Richte die Erfassung ein und lerne die wichtigsten Schritte kennen."] = "New here? Set up capture and learn the essentials.";
    }
